package com.aryaa.sdm.controller;
import com.aryaa.sdm.dto.*; import com.aryaa.sdm.model.PatientStatus; import com.aryaa.sdm.repository.PatientRepository; import com.aryaa.sdm.service.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/patients") public class PatientController{private final PatientIntakeService intake;private final AdmissionService admission;private final PatientRepository repo;public PatientController(PatientIntakeService i,AdmissionService a,PatientRepository r){intake=i;admission=a;repo=r;}@GetMapping public List<PatientDto> getPatients(@RequestParam(required=false) PatientStatus status){var p=status!=null?repo.findByStatus(status):repo.findAll();return p.stream().map(PatientDto::from).toList();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public PatientDto register(@Valid @RequestBody PatientRequest r){return intake.registerPatient(r);}@PostMapping("/bulk") @ResponseStatus(HttpStatus.CREATED) public List<PatientDto> bulk(@Valid @RequestBody BulkPatientRequest r){return intake.registerBulk(r);}@PostMapping("/admit") public AdmissionResult admit(@RequestParam String region){return admission.admitWaitingPatients(region);}@PostMapping("/{id}/discharge") public PatientDto discharge(@PathVariable Long id){return admission.dischargePatient(id);}}
